// Código para n8n - Filtrar usuários por grupos específicos
// Regra: (RETENTION OU WEBCHAT) MENOS ONBOARDING

// IDs dos grupos que queremos filtrar
const retention_group_id = "3ea40078-55f2-4176-85ee-face7f3d7498";
const webchat_group_id = "6b748002-634a-4ba7-b191-844d123643ed";
const onboarding_group_id = "64f40e5f-b18a-4d1d-8c23-1fcb9575c5a7";

// Recebe o input do n8n
const inputData = $input.all();

// Função para verificar se um agente pertence ao grupo de retention ou webchat
function belongsToRetentionOrWebchat(userGroups) {
  if (!userGroups || !Array.isArray(userGroups)) {
    return false;
  }
  return userGroups.includes(retention_group_id) || userGroups.includes(webchat_group_id);
}

// Função para verificar se um agente pertence ao grupo de onboarding
function belongsToOnboarding(userGroups) {
  if (!userGroups || !Array.isArray(userGroups)) {
    return false;
  }
  return userGroups.includes(onboarding_group_id);
}

// Filtra os usuários aplicando a regra: (RETENTION OU WEBCHAT) - ONBOARDING
const filteredUsers = [];

// Itera sobre cada item do input
for (const item of inputData) {
  // Verifica se existe o array de agents
  if (item.json && item.json.agents) {
    const agents = item.json.agents;

    // Aplica a regra de filtro: pertence a retention OU webchat, MAS NÃO pertence a onboarding
    const matchingAgents = agents.filter(agent => {
      const inRetentionOrWebchat = belongsToRetentionOrWebchat(agent.groups);
      const inOnboarding = belongsToOnboarding(agent.groups);

      // Retorna true se está em retention/webchat E NÃO está em onboarding
      return inRetentionOrWebchat && !inOnboarding;
    });

    // Adiciona os usuários filtrados ao resultado
    matchingAgents.forEach(agent => {
      filteredUsers.push({
        json: agent
      });
    });
  }
}

// Retorna os usuários filtrados
return filteredUsers;

// 1. Prepara a lista de agentes (unificando dados reais e mocados)
const agentsData = items.map(item => ({
  name: item.json.agent_name,
  total_90_days: item.json.total,
  isHuman: true 
}));

// Injetando dados mocados conforme solicitado
agentsData.push({ name: "Yooga Suporte", total_90_days: 3634, isHuman: true });
agentsData.push({ name: "Care AI", total_90_days: 14696, isHuman: false });

let totalTenMinCapacity = 0;
let humanAgentCount = 0;
let detailedResults = [];

// 2. Realiza os cálculos de base para cada entidade
agentsData.forEach(agent => {
  const total = agent.total_90_days;

  // Lógica de médias sucessivas
  const mediaMensal = total / 3;
  const mediaDiaria = Math.ceil(mediaMensal / 20); // Arredonda para cima conforme regra
  const mediaHora = mediaDiaria / 8;
  const media10Min = mediaHora / 6;

  // Acumula a capacidade para o cálculo do time
  totalTenMinCapacity += media10Min;

  // Conta apenas humanos para o divisor final
  if (agent.isHuman) {
    humanAgentCount++;
  }

  detailedResults.push({
    agente: agent.name,
    total_trimestral: total,
    media_10_min: parseFloat(media10Min.toFixed(4)),
    tipo: agent.isHuman ? "Humano" : "IA"
  });
});

// 3. Cálculos Finais de Capacidade (Webchat e WhatsApp)

// Capacity Webchat: Soma das médias / quantidade de humanos
const capacity_webchat = humanAgentCount > 0 ? (totalTenMinCapacity / humanAgentCount) : 0;

// Capacity WhatsApp: (Capacity Webchat * 4) / 3
const capacity_whatsapp = (capacity_webchat * 4) / 3;

// Retorno estruturado
return [{
  json: {
    capacity_webchat: parseFloat(capacity_webchat.toFixed(4)),
    capacity_whatsapp: parseFloat(capacity_whatsapp.toFixed(4)),
    total_agentes_humanos: humanAgentCount,
    total_entidades_processadas: agentsData.length,
    detalhes_por_agente: detailedResults
  }
}];

// O n8n recebe os dados em um array chamado 'items'
