  let totalSum = 0;

  // 1. Acessa o array 'data'
  if (item.json.data && Array.isArray(item.json.data)) {
    item.json.data.forEach(dataEntry => {

      // 2. Acessa o array 'series' dentro de cada dataEntry
      if (dataEntry.series && Array.isArray(dataEntry.series)) {
        dataEntry.series.forEach(serie => {

          // 3. Acessa o array 'values' dentro de cada serie
          if (serie.values && Array.isArray(serie.values)) {
            serie.values.forEach(valObj => {

              // 4. Converte a string "16.0" para número e soma
              const numericValue = parseFloat(valObj.value) || 0;
              totalSum += numericValue;
            });
          }
        });
      }
    });
  }

  // Retorna o novo formato desejado
  return {
    json: {
      agent_name: item.json.agent_name.trim(),
      total: totalSum
    }
  };
});

