// Extrai os dados do JSON
const allItems = inputData.map(item => item.json);

// Separa os dados de escala (linhas com row_number) dos dados de capacidade
const scheduleData = [];
const capacityData = {};

for (const item of allItems) {
  if ('row_number' in item) {
    scheduleData.push(item);
  } else if ('capacity_webchat_segunda' in item) {
    capacityData['segunda'] = {
      webchat: item.capacity_webchat_segunda,
      whatsapp: item.capacity_whatsapp_segunda
    };
  } else if ('capacity_webchat_terca' in item) {
    capacityData['terca'] = {
      webchat: item.capacity_webchat_terca,
      whatsapp: item.capacity_whatsapp_terca
    };
  } else if ('capacity_webchat_quarta' in item) {
    capacityData['quarta'] = {
      webchat: item.capacity_webchat_quarta,
      whatsapp: item.capacity_whatsapp_quarta
    };
  } else if ('capacity_webchat_quinta' in item) {
    capacityData['quinta'] = {
      webchat: item.capacity_webchat_quinta,
      whatsapp: item.capacity_whatsapp_quinta
    };
  } else if ('capacity_webchat_sexta' in item) {
    capacityData['sexta'] = {
      webchat: item.capacity_webchat_sexta,
      whatsapp: item.capacity_whatsapp_sexta
    };
