// Limite do Notion (2000 caracteres)
const MAX_LENGTH = 2000;

return items.map(item => {
  const originalText = item.json.output || "";
  const chunks = [];
  let currentChunk = "";

  // 1. Divide o texto por quebras de linha para tentar manter parágrafos
  const paragraphs = originalText.split('\n');

  for (let i = 0; i < paragraphs.length; i++) {
    const paragraph = paragraphs[i];

    // Verifica se adicionar este parágrafo vai estourar o limite (considerando o \n extra)
    if ((currentChunk.length + paragraph.length + 1) > MAX_LENGTH) {

      // Se o chunk atual já tem conteúdo, salvamos ele e limpamos a variável
      if (currentChunk.length > 0) {
        chunks.push(currentChunk);
        currentChunk = "";
      }

      // CASO EXTREMO: O parágrafo sozinho é maior que 2000 caracteres?
      if (paragraph.length > MAX_LENGTH) {
        let tempPara = paragraph;
        // Corta o parágrafo gigante em pedaços de 2000
        while (tempPara.length > 0) {
          // Pega os primeiros 2000 caracteres
          let slice = tempPara.slice(0, MAX_LENGTH);

          // Tenta não cortar uma palavra ao meio: procura o último espaço
          if (tempPara.length > MAX_LENGTH) {
             const lastSpace = slice.lastIndexOf(' ');
             if (lastSpace > 0) slice = slice.slice(0, lastSpace);
          }

          chunks.push(slice);
          tempPara = tempPara.slice(slice.length).trim();
        }
      } else {
        // Se o parágrafo cabe no limite (mas não cabia no chunk anterior), ele inicia o novo chunk
        currentChunk = paragraph;
      }

    } else {
      // Se cabe, adiciona ao chunk atual (com quebra de linha se não for o primeiro)
      if (currentChunk.length > 0) {
        currentChunk += "\n" + paragraph;
      } else {
        currentChunk = paragraph;
      }
    }
  }

  // Adiciona o que sobrou no final
  if (currentChunk.length > 0) {
    chunks.push(currentChunk);
  }

  // Retorna todos os dados originais + o campo novo 'output_chunks'
  return {
    json: {
      ...item.json,
      output_chunks: chunks
    }
  };
});

