// =============================================================
// Acrescenta os novos agentes à escala
// Equivalente JS do input_agents_10_min.py
// =============================================================

// 1. RECEBER OS DADOS
const allItems = $input.all();

if (!allItems || allItems.length === 0) {
  throw new Error("Nenhum item recebido. Verifique a conexão do nó anterior.");
}

// Separar items: linhas da escala vs output da IA
const schedule = [];
let agentsOutput = null;

for (const item of allItems) {
  const json = item.json;
  if ('SEG' in json && 'row_number' in json) {
    schedule.push({ ...json });
  } else if ('output' in json) {
    agentsOutput = json.output;
  }
}

if (schedule.length === 0) {
  throw new Error(
    "Nenhuma linha de escala encontrada.\n" +
    "Campos do primeiro item: [" + Object.keys(allItems[0].json).join(', ') + "]"
  );
}

if (!agentsOutput) {
  throw new Error(
    "Output da IA não encontrado.\n" +
    "Total de items: " + allItems.length
  );
}

// 2. GERAR HORA (grid de 10min a partir de 07:00)
// row_number 2 = 07:00, row_number 3 = 07:10, etc.
for (const row of schedule) {
  if (!row.HORA) {
    const minutesFromStart = (row.row_number - 2) * 10;
    const totalMinutes = (7 * 60) + minutesFromStart;
    const h = Math.floor(totalMinutes / 60) % 24;
    const m = totalMinutes % 60;
    row.HORA = String(h).padStart(2, '0') + ':' + String(m).padStart(2, '0');
  }
}

// 3. PARSE DOS AGENTES (suporta Array OU string Python)
let agents = [];

if (Array.isArray(agentsOutput)) {
  // Formato do Structured Output Parser
  agents = agentsOutput.map(ag => ({
    name: ag.agente,
    start: ag.inicio,
    end: ag.fim,
    days: ag.dias_trabalho
  }));
} else {
  // Formato string Python: "Agente_1": ("09:00", "18:00", ["seg", "ter"])
  const outputStr = String(agentsOutput);
  const lines = outputStr.split('\n');

  for (const line of lines) {
    const trimmed = line.trim();
    // Procura linhas que contêm o padrão de agente
    if (trimmed.includes('Agente_') && trimmed.includes('(') && trimmed.includes('[')) {
      try {
        // Extrair nome do agente
        const nameMatch = trimmed.match(/"([^"]+)"/);
        if (!nameMatch) continue;
        const name = nameMatch[1];

        // Extrair conteúdo entre parênteses: ("09:00", "18:00", ["seg", "ter"])
        const parenStart = trimmed.indexOf('(');
        const parenEnd = trimmed.lastIndexOf(')');
        if (parenStart === -1 || parenEnd === -1) continue;
        const inner = trimmed.substring(parenStart + 1, parenEnd);

        // Extrair os dois horários (primeiras duas strings entre aspas após o parêntese)
        const timeMatches = inner.match(/"(\d{2}:\d{2})"/g);
        if (!timeMatches || timeMatches.length < 2) continue;
        const start = timeMatches[0].replace(/"/g, '');
        const end = timeMatches[1].replace(/"/g, '');

        // Extrair array de dias entre colchetes
        const bracketStart = inner.indexOf('[');
        const bracketEnd = inner.indexOf(']');
        if (bracketStart === -1 || bracketEnd === -1) continue;
        const daysStr = inner.substring(bracketStart + 1, bracketEnd);
        const days = daysStr.split(',').map(d => d.trim().replace(/"/g, '').replace(/'/g, ''));

        agents.push({ name, start, end, days });
      } catch (e) {
        // Se falhar o parse de uma linha, pula para a próxima
        continue;
      }
    }
  }
}

if (agents.length === 0) {
  throw new Error(
    "Nenhum agente encontrado no output da IA.\n" +
    "Primeiros 300 chars: " + String(agentsOutput).substring(0, 300)
  );
}

// 4. MAPEAMENTO DE DIAS (IA usa minúsculo com acento → planilha usa maiúsculo)
const dayMap = {
  'seg': 'SEG', 'ter': 'TER', 'qua': 'QUA', 'qui': 'QUI',
  'sex': 'SEX', 'sáb': 'SABADO', 'sab': 'SABADO',
  'dom': 'DOMINGO'
};

// 5. ADICIONAR AGENTES À ESCALA (lógica do input_agents_10_min.py)
// Equivalente a: df_schedule.loc[(hora >= start) & (hora <= end), day] += 1
for (const agent of agents) {
  for (const day of agent.days) {
    const col = dayMap[day.trim().toLowerCase()] || day.trim();

    for (const row of schedule) {
      if (row[col] !== undefined && row.HORA) {
        // Comparação de horário: suporta agentes que cruzam meia-noite
        // Ex: start="19:00", end="04:00" → trabalha de 19h até 00:00
        // Mas o horário máximo da escala é 00:00, então tratamos normalmente
        if (agent.start <= agent.end) {
          // Turno normal (ex: 07:00 a 16:00)
          if (row.HORA >= agent.start && row.HORA <= agent.end) {
            row[col] += 1;
          }
        } else {
          // Turno que cruza meia-noite (ex: 19:00 a 04:00)
          // Na escala (07:00-00:00), pega de 19:00 até 00:00
          if (row.HORA >= agent.start || row.HORA <= agent.end) {
            row[col] += 1;
          }
        }
      }
    }
  }
}

// 6. RETORNAR A ESCALA ATUALIZADA
return schedule;
